const contentSignal = "Content-Signal: ai-train=yes, search=yes, ai-input=yes";

const robotsGroup = (userAgents: string[], extra?: string) =>
  `${userAgents.map((userAgent) => `User-agent: ${userAgent}`).join("\n")}
${contentSignal}
Allow: /${extra ? `\n${extra}` : ""}`;

const robotsTxt = `# Public crawler policy for nixhil.dev
# Generated dynamically – do not edit this file directly.
# Unknown crawlers inherit the same public-content policy.
${robotsGroup(["*"])}

# Search engine crawlers
${robotsGroup([
  "Googlebot",
  "GoogleOther",
  "Google-InspectionTool",
  "Bingbot",
  "DuckDuckBot",
  "Applebot",
  "YandexBot",
  "Baiduspider",
  "Sogou",
  "360Spider",
  "Slurp",
])}

# AI search and answer crawlers
# Allow: determines ChatGPT Search, Claude Search, Perplexity citability
${robotsGroup([
  "OAI-SearchBot",
  "ChatGPT-User",
  "Claude-SearchBot",
  "Claude-User",
  "PerplexityBot",
  "Perplexity-User",
  "Google-Agent",
  "Google-GeminiNotebook",
  "Amazonbot",
])}

# AI training and grounding crawlers
# Allowed – portfolio content is public; adjust ai-train if licensing changes
${robotsGroup([
  "GPTBot",
  "ClaudeBot",
  "Google-Extended",
  "Bytespider",
  "cohere-ai",
  "CCBot",
  "Applebot-Extended",
])}

# Social preview and professional-network crawlers
${robotsGroup([
  "facebookexternalhit",
  "LinkedInBot",
  "Twitterbot",
  "Slackbot",
  "Discordbot",
  "WhatsApp",
  "TelegramBot",
])}

Sitemap: https://www.nixhil.dev/sitemap.xml
`;

export function GET(): Response {
  return new Response(robotsTxt, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "X-Robots-Tag": "noindex",
      "Cache-Control": "public, max-age=3600, stale-while-revalidate=86400",
    },
  });
}
